// DELIBERATELY WRONG -- generated by stubs/build.mjs, do not edit and do not import from
// anything but the conformance vectors.
// Flip: producer-minted-message-id
// Frozen claim it violates: message_id is protocol-generated and is not part of the payload hash
// This file differs from engine.mjs in exactly 3 place(s).
// Disposable M2 spike. This is the executable form of the frozen SQLite engine details in
// docs/session-protocol-sqlite-engine.md. It is not the production protocol implementation and is
// wired to no adopter: no ORM, no daemon, no outbox, no file observer, no harness callback.
import { createHash, randomBytes } from 'node:crypto'
import { statSync, statfsSync } from 'node:fs'
import { dirname, isAbsolute } from 'node:path'
import { DatabaseSync } from 'node:sqlite'

// The driver is a replaceable implementation detail; the contract is the schema, the migration
// registry, the canonical encoding, the error codes and the version gate. Both candidate bindings
// must pass the identical conformance vectors, and neither may change a byte of the schema.
export const nodeSqliteDriver = {
  name: 'node:sqlite',
  open: (path, { readOnly }) => new DatabaseSync(path, { readOnly }),
}

let defaultDriver = nodeSqliteDriver
export const setDefaultDriver = driver => { defaultDriver = driver }

export const COMPONENT = 'session-protocol'
export const MIN_SQLITE_VERSION = '3.51.3'
export const PROTOCOL_VERSION = 1

export const LIMITS = {
  sessionId: 256,
  messageKind: 64,
  idempotencyKey: 256,
  headerKey: 64,
  headerValueBytes: 4096,
  headerCount: 64,
  headersJsonBytes: 65536,
  bodyBytes: 1048576,
}

// Values read verbatim from /usr/include/linux/magic.h (package linux-libc-dev). FUSE is absent on
// purpose: its magic identifies the driver, not whether the backing store is local.
export const NETWORK_FILESYSTEM_TYPES = [
  { name: 'NFS', type: 0x6969 },
  { name: 'SMB', type: 0x517b },
  { name: 'CIFS', type: 0xff534d42 },
  { name: 'SMB2', type: 0xfe534d42 },
  { name: '9P', type: 0x01021997 },
  { name: 'CEPH', type: 0x00c36400 },
  { name: 'AFS', type: 0x5346414f },
  { name: 'AFS_FS', type: 0x6b414653 },
  { name: 'CODA', type: 0x73757245 },
  { name: 'OCFS2', type: 0x7461636f },
  { name: 'NCP', type: 0x564c },
]

export class ProtocolError extends Error {
  constructor(code, message, cause) {
    super(message, { cause })
    this.name = 'ProtocolError'
    this.code = code
  }
}
const fail = (code, message, cause) => { throw new ProtocolError(code, message, cause) }

// ------------------------------------------------------------------ migrations

const MIGRATION_SQL_V1 = `
CREATE TABLE protocol_sessions (
  session_id     TEXT    NOT NULL PRIMARY KEY,
  created_at_ms  INTEGER NOT NULL,
  retired_at_ms  INTEGER,
  CHECK (length(session_id) BETWEEN 1 AND 256),
  CHECK (session_id NOT GLOB '*[^0-9A-Za-z_-]*'),
  CHECK (session_id NOT GLOB '-*'),
  CHECK (created_at_ms >= 0),
  CHECK (retired_at_ms IS NULL OR retired_at_ms >= 0)
) STRICT;

CREATE TABLE protocol_messages (
  enqueue_seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  message_id         TEXT    NOT NULL UNIQUE,
  target_session_id  TEXT    NOT NULL REFERENCES protocol_sessions(session_id),
  sender_session_id  TEXT,
  protocol_version   INTEGER NOT NULL,
  kind               TEXT    NOT NULL,
  body               BLOB    NOT NULL,
  headers_json       TEXT    NOT NULL,
  idempotency_key    TEXT,
  payload_hash       BLOB    NOT NULL,
  enqueued_at_ms     INTEGER NOT NULL,
  dequeued_at_ms     INTEGER,
  CHECK (message_id GLOB '[0-9a-f]*' AND length(message_id) = 32),
  CHECK (protocol_version >= 1),
  CHECK (length(kind) BETWEEN 1 AND 64),
  CHECK (kind NOT GLOB '*[^0-9A-Za-z._-]*'),
  CHECK (length(body) <= 1048576),
  CHECK (json_valid(headers_json) AND json_type(headers_json) = 'object'),
  CHECK (length(CAST(headers_json AS BLOB)) <= 65536),
  CHECK (idempotency_key IS NULL OR length(idempotency_key) BETWEEN 1 AND 256),
  CHECK (length(payload_hash) = 32),
  CHECK (enqueued_at_ms >= 0),
  CHECK (dequeued_at_ms IS NULL OR dequeued_at_ms >= 0),
  CHECK (sender_session_id IS NULL OR length(sender_session_id) BETWEEN 1 AND 256)
) STRICT;

CREATE UNIQUE INDEX protocol_messages_idempotency
  ON protocol_messages (target_session_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

CREATE INDEX protocol_messages_pending_fifo
  ON protocol_messages (target_session_id, enqueue_seq)
  WHERE dequeued_at_ms IS NULL;

CREATE INDEX protocol_messages_history
  ON protocol_messages (target_session_id, enqueue_seq);
`

const REGISTRY_SQL = `
CREATE TABLE IF NOT EXISTS schema_migrations (
  component      TEXT    NOT NULL,
  version        INTEGER NOT NULL,
  checksum       TEXT    NOT NULL,
  applied_at_ms  INTEGER NOT NULL,
  PRIMARY KEY (component, version)
) STRICT;
`

// Each migration checksums only its own bytes, so appending version N+1 never disturbs version N.
export const MIGRATIONS = [
  { version: 1, sql: MIGRATION_SQL_V1 },
].map(m => ({ ...m, checksum: createHash('sha256').update(Buffer.from(m.sql, 'utf8')).digest('hex') }))

// ------------------------------------------------------------------ gates

export function isSupportedSqliteVersion(version) {
  if (typeof version !== 'string') return false
  const parse = v => v.split('.').map(Number)
  const [a, b, c] = parse(version)
  if (![a, b, c].every(Number.isInteger)) return false
  const [x, y, z] = parse(MIN_SQLITE_VERSION)
  if (a !== x) return a > x
  if (b !== y) return b > y
  return c >= z
}

export function isRejectedFilesystemType(type) {
  return NETWORK_FILESYSTEM_TYPES.some(entry => entry.type === type)
}

// ------------------------------------------------------------------ canonical bytes

const u32 = n => { const b = Buffer.alloc(4); b.writeUInt32BE(n); return b }
const u64 = n => { const b = Buffer.alloc(8); b.writeBigUInt64BE(BigInt(n)); return b }
const field = s => { const u = Buffer.from(s, 'utf8'); return Buffer.concat([u32(u.length), u]) }
const optField = s => (s === null || s === undefined ? Buffer.from([0]) : Buffer.concat([Buffer.from([1]), field(s)]))

// Length-prefixed binary framing, not JSON: no escaping, no locale, no unicode-normalisation choice.
// Header keys are ASCII-only, so ascending UTF-8 byte order is unambiguous in every language.
export function canonicalPreimage(message) {
  const keys = Object.keys(message.headers ?? {}).sort(
    (a, b) => Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8')),
  )
  const body = Buffer.from(message.body)
  return Buffer.concat([
    u32(message.protocolVersion),
    field(message.targetSessionId),
    optField(message.senderSessionId ?? null),
    field(message.kind),
    u32(keys.length),
    ...keys.flatMap(k => [field(k), field(message.headers[k])]),
    u64(body.length),
    body,
  ])
}

export const payloadHash = message => createHash('sha256').update(canonicalPreimage(message)).digest()

// ------------------------------------------------------------------ validation

const SESSION_ID_RE = /^[0-9A-Za-z_][0-9A-Za-z_-]*$/
const KIND_RE = /^[0-9A-Za-z._-]+$/
const HEADER_KEY_RE = /^[0-9A-Za-z._-]+$/

function requireSessionId(value, what = 'sessionId') {
  if (typeof value !== 'string') fail('PROTOCOL_SESSION_ID_INVALID', `${what} must be a string`)
  if (value.length < 1 || value.length > LIMITS.sessionId) {
    fail('PROTOCOL_SESSION_ID_INVALID', `${what} must be 1..${LIMITS.sessionId} characters`)
  }
  if (!SESSION_ID_RE.test(value)) {
    fail('PROTOCOL_SESSION_ID_INVALID', `${what} must match [0-9A-Za-z_][0-9A-Za-z_-]* (got ${JSON.stringify(value)})`)
  }
  return value
}

function normalizeMessage(targetSessionId, input) {
  if (!input || typeof input !== 'object') fail('PROTOCOL_MESSAGE_INVALID', 'message must be an object')
  const suppliedMessageId = typeof input.messageId === 'string' && input.messageId
    ? input.messageId
    : randomBytes(16).toString('hex')
  if ('targetSessionId' in input && input.targetSessionId !== targetSessionId) {
    fail('PROTOCOL_MESSAGE_INVALID', 'targetSessionId must equal the enqueue address')
  }

  const protocolVersion = input.protocolVersion ?? PROTOCOL_VERSION
  if (!Number.isInteger(protocolVersion) || protocolVersion < 1) {
    fail('PROTOCOL_MESSAGE_INVALID', 'protocolVersion must be a positive integer')
  }

  const kind = input.kind
  if (typeof kind !== 'string' || kind.length < 1 || kind.length > LIMITS.messageKind || !KIND_RE.test(kind)) {
    fail('PROTOCOL_MESSAGE_INVALID', `kind must match [0-9A-Za-z._-]{1,${LIMITS.messageKind}}`)
  }

  // Opaque bytes only. Accepting a string would make the protocol choose an encoding on the
  // producer's behalf, which is exactly the kind of hidden authority this refactor removes.
  if (!(input.body instanceof Uint8Array)) {
    fail('PROTOCOL_MESSAGE_INVALID', 'body must be a Uint8Array; encode strings before enqueue')
  }
  const body = Buffer.from(input.body)
  if (body.length > LIMITS.bodyBytes) {
    fail('PROTOCOL_MESSAGE_INVALID', `body exceeds ${LIMITS.bodyBytes} bytes`)
  }

  const senderSessionId = input.senderSessionId ?? null
  if (senderSessionId !== null) requireSessionId(senderSessionId, 'senderSessionId')

  const idempotencyKey = input.idempotencyKey ?? null
  if (idempotencyKey !== null) {
    if (typeof idempotencyKey !== 'string' || idempotencyKey.length < 1 || idempotencyKey.length > LIMITS.idempotencyKey) {
      fail('PROTOCOL_MESSAGE_INVALID', `idempotencyKey must be 1..${LIMITS.idempotencyKey} characters`)
    }
  }

  const headersInput = input.headers ?? {}
  if (typeof headersInput !== 'object' || headersInput === null || Array.isArray(headersInput)) {
    fail('PROTOCOL_MESSAGE_INVALID', 'headers must be a plain object')
  }
  const keys = Object.keys(headersInput)
  if (keys.length > LIMITS.headerCount) fail('PROTOCOL_MESSAGE_INVALID', `at most ${LIMITS.headerCount} headers`)
  for (const key of keys) {
    if (key.length < 1 || key.length > LIMITS.headerKey || !HEADER_KEY_RE.test(key)) {
      fail('PROTOCOL_MESSAGE_INVALID', `header key must match [0-9A-Za-z._-]{1,${LIMITS.headerKey}} (got ${JSON.stringify(key)})`)
    }
    if (typeof headersInput[key] !== 'string') {
      fail('PROTOCOL_MESSAGE_INVALID', `header ${key} must be a string`)
    }
    if (Buffer.byteLength(headersInput[key], 'utf8') > LIMITS.headerValueBytes) {
      fail('PROTOCOL_MESSAGE_INVALID', `header ${key} exceeds ${LIMITS.headerValueBytes} bytes`)
    }
  }
  const sortedKeys = [...keys].sort((a, b) => Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8')))
  const headers = Object.fromEntries(sortedKeys.map(k => [k, headersInput[k]]))
  const headersJson = JSON.stringify(headers)
  if (Buffer.byteLength(headersJson, 'utf8') > LIMITS.headersJsonBytes) {
    fail('PROTOCOL_MESSAGE_INVALID', `headers exceed ${LIMITS.headersJsonBytes} bytes`)
  }

  const envelope = { protocolVersion, targetSessionId, senderSessionId, kind, headers, body }
  const hash = createHash('sha256').update(canonicalPreimage(envelope)).update(suppliedMessageId).digest()
  return { ...envelope, suppliedMessageId, idempotencyKey, headersJson, payloadHash: hash }
}

// ------------------------------------------------------------------ error mapping

function classify(error) {
  const code = String(error?.code ?? '')
  if (code === 'SQLITE_BUSY' || code === 'SQLITE_LOCKED') return 'PROTOCOL_DATABASE_BUSY'
  if (code === 'SQLITE_READONLY') return 'PROTOCOL_DATABASE_READONLY'
  if (code === 'SQLITE_CORRUPT' || code === 'SQLITE_NOTADB') return 'PROTOCOL_DATABASE_CORRUPT'
  if (code === 'SQLITE_CANTOPEN') return 'PROTOCOL_DATABASE_UNAVAILABLE'
  const text = String(error?.message ?? error)
  if (/database is locked|database table is locked|SQLITE_BUSY/i.test(text)) return 'PROTOCOL_DATABASE_BUSY'
  if (/readonly|read-only|attempt to write/i.test(text)) return 'PROTOCOL_DATABASE_READONLY'
  if (/malformed|not a database|disk image|corrupt/i.test(text)) return 'PROTOCOL_DATABASE_CORRUPT'
  if (/unable to open database/i.test(text)) return 'PROTOCOL_DATABASE_UNAVAILABLE'
  return null
}

const rethrow = error => {
  if (error instanceof ProtocolError) throw error
  fail(classify(error) ?? 'PROTOCOL_SQLITE_ERROR', String(error?.message ?? error), error)
}

// ------------------------------------------------------------------ open

function validateDatabasePath(databasePath) {
  if (typeof databasePath !== 'string' || databasePath.length === 0 || !isAbsolute(databasePath)) {
    fail('PROTOCOL_PATH_NOT_ABSOLUTE', 'databasePath must be an absolute filesystem path string')
  }
  if (databasePath.includes('\0')) fail('PROTOCOL_PATH_INVALID', 'databasePath must not contain a NUL byte')
  if (databasePath.endsWith('/')) fail('PROTOCOL_PATH_INVALID', 'databasePath must name a file, not a directory')
}

function checkParentDirectory(databasePath) {
  const parent = dirname(databasePath)
  let stat
  try {
    stat = statSync(parent)
  } catch (error) {
    fail('PROTOCOL_PATH_PARENT_MISSING', `database parent directory does not exist: ${parent}`, error)
  }
  if (!stat.isDirectory()) fail('PROTOCOL_PATH_PARENT_MISSING', `database parent is not a directory: ${parent}`)
  try {
    const fsType = statfsSync(parent).type
    if (isRejectedFilesystemType(fsType)) {
      const name = NETWORK_FILESYSTEM_TYPES.find(e => e.type === fsType).name
      fail('PROTOCOL_PATH_UNSUPPORTED_FILESYSTEM', `WAL requires a same-host filesystem; ${parent} is ${name}`)
    }
  } catch (error) {
    if (error instanceof ProtocolError) throw error
    // statfs is unavailable on this platform: the journal_mode assertion below is the only guard.
  }
}

// Measured: `PRAGMA journal_mode=WAL` takes an exclusive lock and is the one statement that does
// NOT honour busy_timeout, so processes opening a brand-new database together lose the race with a
// bare `database is locked`. Two rules together remove it: read the mode first so a database that is
// already WAL never contends at all, and bound-retry only the genuine first-open collision.
const sleepSync = ms => {
  const buffer = new Int32Array(new SharedArrayBuffer(4))
  Atomics.wait(buffer, 0, 0, ms)
}

function retryWhileBusy(budgetMs, fn) {
  const deadline = Date.now() + Math.max(budgetMs, 1)
  for (;;) {
    try {
      return fn()
    } catch (error) {
      const busy = error instanceof ProtocolError
        ? error.code === 'PROTOCOL_DATABASE_BUSY'
        : classify(error) === 'PROTOCOL_DATABASE_BUSY'
      if (!busy || Date.now() >= deadline) throw error
      sleepSync(20)
    }
  }
}

function ensureWalMode(db, busyTimeoutMs) {
  const current = db.prepare('PRAGMA journal_mode').get().journal_mode
  if (current === 'wal') return current
  const deadline = Date.now() + Math.max(busyTimeoutMs, 1)
  for (;;) {
    try {
      return db.prepare('PRAGMA journal_mode=WAL').get().journal_mode
    } catch (error) {
      if (classify(error) !== 'PROTOCOL_DATABASE_BUSY' || Date.now() >= deadline) throw error
      sleepSync(25)
      const settled = db.prepare('PRAGMA journal_mode').get().journal_mode
      if (settled === 'wal') return settled
    }
  }
}

export function openProtocol(databasePath, options = {}) {
  validateDatabasePath(databasePath)
  const readOnly = options.readOnly === true
  const busyTimeoutMs = Math.max(0, Math.trunc(options.busyTimeoutMs ?? 5000))
  const now = options.now ?? (() => Date.now())
  if (!readOnly) checkParentDirectory(databasePath)

  let db
  const driver = options.driver ?? defaultDriver
  try {
    db = driver.open(databasePath, { readOnly })
  } catch (error) { rethrow(error) }

  try {
    // busy_timeout must be the FIRST statement on the connection. It defaults to 0, so any earlier
    // statement runs with no busy handler at all and loses a contended lock immediately -- measured:
    // that made the version probe the flakiest statement in the whole engine.
    db.exec(`PRAGMA busy_timeout=${busyTimeoutMs}`)
    const version = db.prepare('SELECT sqlite_version() AS v').get().v
    if (!isSupportedSqliteVersion(version)) {
      fail('PROTOCOL_SQLITE_VERSION_UNSUPPORTED',
        `SQLite ${version} carries the WAL-reset corruption bug; ${MIN_SQLITE_VERSION} or later is required`)
    }
    db.exec('PRAGMA foreign_keys=ON')
    if (db.prepare('PRAGMA foreign_keys').get().foreign_keys !== 1) {
      fail('PROTOCOL_PRAGMA_UNSUPPORTED', 'foreign_keys could not be enabled')
    }
    // Opening is not lock-free. The first connection after the WAL was reset rebuilds the -shm
    // wal-index under a brief exclusive lock, and concurrent openers see SQLITE_BUSY from an
    // ordinary read. Bound the retry to the same budget the caller gave for write contention;
    // runtime operations keep surfacing busy loudly, because only startup is transient this way.
    retryWhileBusy(busyTimeoutMs, () => {
      if (!readOnly) {
        const mode = ensureWalMode(db, busyTimeoutMs)
        if (mode !== 'wal') {
          fail('PROTOCOL_JOURNAL_MODE_UNSUPPORTED', `journal_mode is ${mode}, not wal; this filesystem cannot host the protocol`)
        }
        db.exec('PRAGMA synchronous=FULL')
        if (db.prepare('PRAGMA synchronous').get().synchronous !== 2) {
          fail('PROTOCOL_PRAGMA_UNSUPPORTED', 'synchronous could not be set to FULL')
        }
      }
      migrate(db, readOnly, now)
    })
  } catch (error) {
    try { db.close() } catch {}
    rethrow(error)
  }

  return buildHandle(db, { databasePath, readOnly, busyTimeoutMs, now })
}

function readAppliedMigrations(db) {
  const registryExists = db.prepare(
    "SELECT 1 AS present FROM sqlite_master WHERE type='table' AND name='schema_migrations'",
  ).get()
  if (!registryExists) return null
  return db.prepare(
    'SELECT version, checksum FROM schema_migrations WHERE component=? ORDER BY version',
  ).all(COMPONENT)
}

function verifyApplied(applied) {
  const highest = MIGRATIONS[MIGRATIONS.length - 1].version
  if (applied.length > 0 && applied[applied.length - 1].version > highest) {
    fail('PROTOCOL_SCHEMA_GENERATION_UNSUPPORTED',
      `database carries schema generation ${applied[applied.length - 1].version}; this build understands up to ${highest}`)
  }
  for (let i = 0; i < applied.length; i++) {
    if (applied[i].version !== i + 1) {
      fail('PROTOCOL_SCHEMA_GENERATION_UNSUPPORTED',
        `applied migration sequence has a gap at version ${i + 1}`)
    }
    if (applied[i].checksum !== MIGRATIONS[i].checksum) {
      fail('PROTOCOL_SCHEMA_CHECKSUM_MISMATCH',
        `migration ${applied[i].version} was rewritten after it was applied`)
    }
  }
  return applied.length
}

const protocolObjectsExist = db =>
  Boolean(db.prepare("SELECT 1 AS present FROM sqlite_master WHERE type='table' AND name='protocol_sessions'").get())

function migrate(db, readOnly, now) {
  const applied = readAppliedMigrations(db)
  if (readOnly) {
    if (applied === null || applied.length !== MIGRATIONS.length) {
      fail('PROTOCOL_SCHEMA_GENERATION_UNSUPPORTED',
        'read-only database is not migrated to this schema generation')
    }
    verifyApplied(applied)
    return
  }
  if (applied !== null && verifyApplied(applied) === MIGRATIONS.length) return

  // Re-read inside the write transaction: two processes opening a fresh database race here, and the
  // loser must observe the winner's committed work rather than replay the DDL.
  db.exec('BEGIN IMMEDIATE')
  try {
    db.exec(REGISTRY_SQL)
    const done = verifyApplied(readAppliedMigrations(db) ?? [])
    if (done === 0 && protocolObjectsExist(db)) {
      fail('PROTOCOL_SCHEMA_REGISTRY_INCONSISTENT',
        'protocol tables exist but schema_migrations does not account for them')
    }
    const insert = db.prepare(
      'INSERT INTO schema_migrations(component,version,checksum,applied_at_ms) VALUES(?,?,?,?)',
    )
    for (const migration of MIGRATIONS.slice(done)) {
      db.exec(migration.sql)
      insert.run(COMPONENT, migration.version, migration.checksum, now())
    }
    db.exec('COMMIT')
  } catch (error) {
    try { db.exec('ROLLBACK') } catch {}
    throw error
  }
}

// ------------------------------------------------------------------ handle

const SELECT_COLUMNS = `enqueue_seq, message_id, target_session_id, sender_session_id, protocol_version,
  kind, body, headers_json, idempotency_key, payload_hash, enqueued_at_ms, dequeued_at_ms`

const toMessage = row => ({
  enqueueSeq: Number(row.enqueue_seq),
  messageId: row.message_id,
  targetSessionId: row.target_session_id,
  senderSessionId: row.sender_session_id,
  protocolVersion: Number(row.protocol_version),
  kind: row.kind,
  body: Buffer.from(row.body),
  headers: JSON.parse(row.headers_json),
  idempotencyKey: row.idempotency_key,
  payloadHash: Buffer.from(row.payload_hash).toString('hex'),
  enqueuedAtMs: Number(row.enqueued_at_ms),
  dequeuedAtMs: row.dequeued_at_ms === null ? null : Number(row.dequeued_at_ms),
})

// INDEXED BY is part of the contract, not tuning. Measured: with the history index present and no
// ANALYZE statistics, the planner serves the pending head from the full index and the hottest
// protocol operation gets 10x slower. Pinning makes the plan a property of the schema instead of a
// property of whether somebody remembered to collect statistics.
const SQL = {
  session: 'SELECT session_id, created_at_ms, retired_at_ms FROM protocol_sessions WHERE session_id=?',
  head: `SELECT ${SELECT_COLUMNS} FROM protocol_messages INDEXED BY protocol_messages_pending_fifo
         WHERE target_session_id=? AND dequeued_at_ms IS NULL ORDER BY enqueue_seq LIMIT 1`,
  pending: `SELECT ${SELECT_COLUMNS} FROM protocol_messages INDEXED BY protocol_messages_pending_fifo
            WHERE target_session_id=? AND dequeued_at_ms IS NULL ORDER BY enqueue_seq`,
  history: `SELECT ${SELECT_COLUMNS} FROM protocol_messages INDEXED BY protocol_messages_history
            WHERE target_session_id=? AND enqueue_seq>? ORDER BY enqueue_seq`,
  byKey: `SELECT ${SELECT_COLUMNS} FROM protocol_messages INDEXED BY protocol_messages_idempotency
          WHERE target_session_id=? AND idempotency_key=?`,
}

function buildHandle(db, config) {
  const { readOnly, now } = config

  const write = fn => {
    if (readOnly) fail('PROTOCOL_DATABASE_READONLY', 'this handle was opened read-only')
    try {
      db.exec('BEGIN IMMEDIATE')
    } catch (error) { rethrow(error) }
    let value
    try {
      value = fn()
    } catch (error) {
      try { db.exec('ROLLBACK') } catch {}
      rethrow(error)
    }
    try {
      db.exec('COMMIT')
    } catch (error) {
      try { db.exec('ROLLBACK') } catch {}
      rethrow(error)
    }
    return value
  }

  const read = fn => { try { return fn() } catch (error) { rethrow(error) } }

  const requireAddress = (sessionId, { allowRetired = false } = {}) => {
    const row = db.prepare(SQL.session).get(sessionId)
    if (!row) fail('PROTOCOL_SESSION_UNKNOWN', `unknown protocol address: ${sessionId}`)
    if (!allowRetired && row.retired_at_ms !== null) {
      fail('PROTOCOL_SESSION_RETIRED', `protocol address is retired: ${sessionId}`)
    }
    return row
  }

  const insertMessage = (sessionId, input) => {
    const message = normalizeMessage(sessionId, input)
    requireAddress(sessionId)
    if (message.idempotencyKey !== null) {
      const prior = db.prepare(SQL.byKey).get(sessionId, message.idempotencyKey)
      if (prior) {
        if (Buffer.compare(Buffer.from(prior.payload_hash), message.payloadHash) !== 0) {
          fail('PROTOCOL_IDEMPOTENCY_CONFLICT',
            `idempotency key ${message.idempotencyKey} was reused with different message bytes`)
        }
        return toMessage(prior)
      }
    }
    const messageId = message.suppliedMessageId
    const stamped = now()
    db.prepare(`INSERT INTO protocol_messages
      (message_id, target_session_id, sender_session_id, protocol_version, kind, body,
       headers_json, idempotency_key, payload_hash, enqueued_at_ms, dequeued_at_ms)
      VALUES (?,?,?,?,?,?,?,?,?,?,NULL)`).run(
      messageId, sessionId, message.senderSessionId, message.protocolVersion, message.kind,
      message.body, message.headersJson, message.idempotencyKey, message.payloadHash, stamped,
    )
    return toMessage(db.prepare(`SELECT ${SELECT_COLUMNS} FROM protocol_messages WHERE message_id=?`).get(messageId))
  }

  return {
    databasePath: config.databasePath,
    readOnly,

    initialize(sessionId) {
      requireSessionId(sessionId)
      return write(() => {
        const existing = db.prepare(SQL.session).get(sessionId)
        if (existing) {
          if (existing.retired_at_ms !== null) {
            fail('PROTOCOL_SESSION_RETIRED', `protocol address is retired and cannot be resurrected: ${sessionId}`)
          }
          return { sessionId, createdAtMs: Number(existing.created_at_ms), retiredAtMs: null }
        }
        const createdAtMs = now()
        db.prepare('INSERT INTO protocol_sessions(session_id, created_at_ms, retired_at_ms) VALUES(?,?,NULL)')
          .run(sessionId, createdAtMs)
        return { sessionId, createdAtMs, retiredAtMs: null }
      })
    },

    enqueue(sessionId, input) {
      requireSessionId(sessionId)
      return write(() => insertMessage(sessionId, input))
    },

    dequeue(sessionId) {
      requireSessionId(sessionId)
      return write(() => {
        requireAddress(sessionId)
        const row = db.prepare(SQL.head).get(sessionId)
        if (!row) return null
        const stamped = now()
        const result = db.prepare(
          'UPDATE protocol_messages SET dequeued_at_ms=? WHERE enqueue_seq=? AND dequeued_at_ms IS NULL',
        ).run(stamped, row.enqueue_seq)
        if (result.changes !== 1) {
          fail('PROTOCOL_SQLITE_ERROR', 'FIFO head changed inside a write transaction')
        }
        return toMessage({ ...row, dequeued_at_ms: stamped })
      })
    },

    listPending(sessionId) {
      requireSessionId(sessionId)
      return read(() => {
        requireAddress(sessionId, { allowRetired: true })
        return db.prepare(SQL.pending).all(sessionId).map(toMessage)
      })
    },

    readMessages(sessionId, afterSequence = 0) {
      requireSessionId(sessionId)
      if (!Number.isInteger(afterSequence) || afterSequence < 0) {
        fail('PROTOCOL_CURSOR_INVALID', 'afterSequence must be a non-negative integer')
      }
      return read(() => {
        requireAddress(sessionId, { allowRetired: true })
        return db.prepare(SQL.history).all(sessionId, afterSequence).map(toMessage)
      })
    },

    retire(sessionId) {
      requireSessionId(sessionId)
      return write(() => {
        const row = requireAddress(sessionId, { allowRetired: true })
        if (row.retired_at_ms !== null) {
          return { sessionId, createdAtMs: Number(row.created_at_ms), retiredAtMs: Number(row.retired_at_ms) }
        }
        const pending = db.prepare(
          'SELECT 1 AS present FROM protocol_messages WHERE target_session_id=? AND dequeued_at_ms IS NULL LIMIT 1',
        ).get(sessionId)
        if (pending) fail('PROTOCOL_RETIRE_NON_EMPTY', `cannot retire an address with pending messages: ${sessionId}`)
        const retiredAtMs = now()
        db.prepare('UPDATE protocol_sessions SET retired_at_ms=? WHERE session_id=? AND retired_at_ms IS NULL')
          .run(retiredAtMs, sessionId)
        return { sessionId, createdAtMs: Number(row.created_at_ms), retiredAtMs }
      })
    },

    withTransaction(callback) {
      if (typeof callback !== 'function') fail('PROTOCOL_TRANSACTION_INVALID', 'a transaction callback is required')
      if (callback.constructor?.name === 'AsyncFunction') {
        fail('PROTOCOL_TRANSACTION_INVALID', 'a transaction body must be synchronous; awaiting inside a write lock is forbidden')
      }
      return write(() => {
        const value = callback({
          exec: (sql, ...params) => db.prepare(sql).run(...params),
          query: (sql, ...params) => db.prepare(sql).all(...params),
          enqueue: (sessionId, input) => {
            requireSessionId(sessionId)
            return insertMessage(sessionId, input)
          },
        })
        if (value && typeof value.then === 'function') {
          fail('PROTOCOL_TRANSACTION_INVALID', 'a transaction body must not return a promise')
        }
        return value
      })
    },

    // --- spike-only inspection, not part of the protocol surface
    pragmas: () => ({
      journal_mode: db.prepare('PRAGMA journal_mode').get().journal_mode,
      foreign_keys: db.prepare('PRAGMA foreign_keys').get().foreign_keys,
      synchronous: db.prepare('PRAGMA synchronous').get().synchronous,
      busy_timeout: db.prepare('PRAGMA busy_timeout').get().timeout,
    }),
    counts: () => ({
      sessions: Number(db.prepare('SELECT count(*) AS c FROM protocol_sessions').get().c),
      messages: Number(db.prepare('SELECT count(*) AS c FROM protocol_messages').get().c),
    }),
    dataVersion: () => Number(db.prepare('PRAGMA data_version').get().data_version),
    queryPlans: () => {
      const plan = (sql, ...params) =>
        db.prepare('EXPLAIN QUERY PLAN ' + sql).all(...params).map(r => r.detail).join(' | ')
      return {
        dequeueHead: plan(SQL.head, 's'),
        listPending: plan(SQL.pending, 's'),
        readMessages: plan(SQL.history, 's', 0),
        idempotencyLookup: plan(SQL.byKey, 's', 'k'),
      }
    },
    close: () => db.close(),
  }
}
